  FROM chk03_daily_list_write
 WHERE chk03_company_id    = #{companyId}
   AND chk03_daily_list_id = #{dailyListId}
   AND chk03_person_id     = #{personId}
   AND chk03_date          = #{date}
 ORDER BY chk03_daily_list_write_id

SELECT 
  FROM chk03_daily_list_write
 WHERE chk03_daily_list_write_id = #{dailyListWriteId}
   AND chk03_company_id = #{companyId}
   AND chk03_person_id  = #{personId}

