UPDATE chk03_daily_list_write
   SET chk03_answer_cd       = #{answerCode},
       chk03_answer_datetime = #{date}
 WHERE chk03_daily_list_write_id = #{dailyListWriteId}
   AND chk03_company_id = #{companyId}
   AND chk03_person_id  = #{personId}

UPDATE chk03_daily_list_write
   SET chk03_reason = #{reason}
 WHERE chk03_daily_list_write_id = #{dailyListWriteId}
   AND chk03_company_id = #{companyId}
   AND chk03_person_id  = #{personId}

UPDATE chk03_daily_list_write
   SET chk03_note = #{note}
 WHERE chk03_daily_list_write_id = #{dailyListWriteId}
   AND chk03_company_id = #{companyId}
   AND chk03_person_id  = #{personId}

UPDATE chk03_daily_list_write
   SET chk03_confirm_yn       = #{confirmYn},
       chk03_confirmer_id     = #{confirmerId},
       chk03_confirm_datetime = now()
 WHERE chk03_daily_list_write_id = #{dailyListWriteId}
   AND chk03_company_id = #{companyId}
